class WebAuthnAuthenticator(ScalewayModel):
    id: str = ""
    """
    ID of the WebAuthn Authenticator.
    """
    name: str = ""
    """
    Name of the WebAuthn Authenticator.
    """
    created_at: datetime | None = None
    """
    Date the WebAuthn Authenticator was created. (RFC 3339 format)
    """
    last_login_at: datetime | None = None
    """
    Date the WebAuthn Authenticator was last successfully used for a LogIn.
    Date the WebAuthn Authenticator was last successfully used for a LogIn, will be
    omitted if the WebAuthn Authenticator has never been used. (RFC 3339 format)
    """
    uv_verified: bool = False
    """
    Indicates whether the authenticator has been verified to perform User Verification
    (UV) by the legitimate owner.
    This flag prevents an attack where a lost, non-UV authenticator (e.g., a PIN-less
    hardware key used only as a second factor) is found by an attacker who then adds a
    PIN to it to bypass MFA via a passwordless login. To mitigate this, the system will
    not trust the authenticator for single-factor (passwordless) login until it
    successfully performs UV in conjunction with another trusted factor.
    """
